  FROM found_item f

 WHERE f.found_id = #{foundId,jdbcType=INTEGER}

mapper.update:
UPDATE found_item
   SET status = 3
 WHERE found_id = #{foundId,jdbcType=INTEGER}
   AND user_id = #{userId,jdbcType=VARCHAR}
   AND status IN (0, 1)

UPDATE found_item
   SET audit_status = 0, audit_remark = NULL, audit_time = NULL
 WHERE found_id = #{foundId,jdbcType=INTEGER}
   AND user_id = #{userId,jdbcType=VARCHAR}
   AND audit_status = 2
   AND status <> 3

